-- Six MIT-licensed layout adaptations; provenance and full notices ship in Web public/third-party/template-notices.txt.
-- Insert only: preserve user snapshots, disabled rows and reject conflicting stable keys.
ON DUPLICATE KEY UPDATE is_active = IF(name = VALUES(name) AND description = VALUES(description) AND data_json = VALUES(data_json) AND style_json = VALUES(style_json), is_active, NULL);
